93	        drop(gate_proj);
94	        drop(up_proj);
95	        Ok(Self {
96	            gate_up_proj,
97	            down_proj: src
98	                .col_shard_if_needed(&format!("{prefix}.mlp.down_proj.weight"), src.intermediate)?,
99	        })
