191	/// One config-derived extent this rank owns, paired with the full extent it was
192	/// cut from. The sharded loads assert the checkpoint's global shape before
193	/// slicing, so range and global are built together and a call site cannot pair
194	/// one extent's range with another's global.
195	#[derive(Clone, Copy)]
196	struct Shard {
197	    /// `(offset, len)` this rank owns.
198	    range: (usize, usize),
199	    /// The pre-shard extent from `config.json`.
200	    global: usize,
201	}
202	
203	impl Shard {
204	    /// A flat shard of `global` rows (or columns) across the TP ranks.
205	    fn flat(global: usize, geometry: LocalGeometry) -> Self {
206	        Self {
207	            range: geometry.shard_range(global),
208	            global,
209	        }
210	    }
211	}
