213	/// The fused linear-attention qkv projection shard: this rank's row slice
214	/// inside each of the three global segments, plus the fused global row count.
215	#[derive(Clone, Copy)]
216	struct LinearQkvShard {
217	    segments: [(usize, usize); 3],
218	    global: usize,
219	}
