221	/// One model load's tensor source plus the loop-invariant TP shard ranges the
222	/// per-layer loaders consume. Construct once per load; every loader names only
223	/// the tensor it wants.
224	pub(super) struct WeightSource<'a> {
225	    ctx: &'a DeviceContext,
226	    shards: &'a [SafeTensors<'a>],
227	    weight_map: &'a HashMap<String, usize>,
228	    geometry: LocalGeometry,
229	    /// Model width every unsharded projection must carry, so a checkpoint whose
230	    /// tensors disagree with its `config.json` stops at the loader instead of
231	    /// reaching a GEMM sized from the config.
232	    hidden: usize,
233	    /// Full-attention q_proj rows as per-head [q, gate] chunks.
234	    gated_q: Shard,
235	    /// o_proj column shard over the full-attention q dim.
236	    q_cols: Shard,
237	    /// k/v_proj row shard.
238	    kv_rows: Shard,
239	    /// MLP intermediate row (gate/up) and column (down) shard.
240	    intermediate: Shard,
241	    /// Linear-attention value-head unit: in_proj_b/a rows, dt_bias, A_log.
242	    linear_value_heads: Shard,
243	    /// Linear-attention z dim: in_proj_z rows and out_proj columns.
244	    linear_z: Shard,
245	    /// Per-segment row slices inside the fused linear qkv projection.
246	    linear_qkv: LinearQkvShard,
247	    /// The same slices in conv1d channel-tap units.
248	    linear_conv1d: [(usize, usize); 3],
249	}
250	
251	impl<'a> WeightSource<'a> {
252	    pub(super) fn new(
253	        ctx: &'a DeviceContext,
254	        shards: &'a [SafeTensors<'a>],
255	        weight_map: &'a HashMap<String, usize>,
256	        config: &Config35,
257	        geometry: LocalGeometry,
258	    ) -> Self {
259	        let linear_qkv = linear_qkv_shard(config, geometry);
260	        Self {
261	            ctx,
262	            shards,
263	            weight_map,
264	            geometry,
265	            hidden: config.hidden_size,
266	            gated_q: full_attention_gated_q_shard(config, geometry),
267	            q_cols: Shard::flat(config.full_attn_q_dim(), geometry),
268	            kv_rows: Shard::flat(config.full_attn_kv_dim(), geometry),
269	            intermediate: Shard::flat(config.intermediate_size, geometry),
270	            linear_value_heads: Shard::flat(config.linear_num_value_heads, geometry),
271	            linear_z: Shard::flat(config.linear_attn_z_dim(), geometry),
272	            linear_qkv,
273	            linear_conv1d: conv1d_shard_segments(linear_qkv, config.linear_conv_kernel_dim),
274	        }
275	    }
276	
277	    pub(super) fn tensor_2d(&self, name: &str, rows: usize, cols: usize) -> Result<DeviceMatrix> {
278	        load_tensor_2d(self.ctx, self.shards, self.weight_map, name, rows, cols)
279	    }
280	
281	    pub(super) fn tensor_1d(&self, name: &str) -> Result<DeviceVec> {
282	        load_tensor_1d(self.ctx, self.shards, self.weight_map, name)
283	    }
284	
285	    fn row_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceMatrix> {
286	        if self.geometry.is_sharded() {
287	            let (row_offset, rows) = shard.range;
288	            load_tensor_2d_row_shard(
289	                self.ctx,
290	                self.shards,
291	                self.weight_map,
292	                name,
293	                row_offset,
294	                rows,
295	                (shard.global, self.hidden),
296	            )
297	        } else {
298	            self.tensor_2d(name, shard.global, self.hidden)
299	        }
300	    }
301	
302	    fn col_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceMatrix> {
303	        if self.geometry.is_sharded() {
304	            let (col_offset, cols) = shard.range;
305	            load_tensor_2d_col_shard(
306	                self.ctx,
307	                self.shards,
308	                self.weight_map,
309	                name,
310	                col_offset,
311	                cols,
312	                (self.hidden, shard.global),
313	            )
314	        } else {
315	            self.tensor_2d(name, self.hidden, shard.global)
316	        }
317	    }
318	
319	    fn tensor_1d_shard_if_needed(&self, name: &str, shard: Shard) -> Result<DeviceVec> {
320	        if self.geometry.is_sharded() {
321	            load_tensor_1d_stitch(self.ctx, self.shards, self.weight_map, name, &[shard.range])
322	        } else {
323	            self.tensor_1d(name)
324	        }
325	    }
326	
327	    fn tensor_1d_f32_shard_if_needed(&self, name: &str, shard: Shard) -> Result<CudaSlice<f32>> {
328	        let (offset, len) = shard.range;
329	        if self.geometry.is_sharded() {
330	            load_tensor_1d_f32_shard(self.ctx, self.shards, self.weight_map, name, offset, len)
331	        } else {
332	            load_tensor_1d_f32(self.ctx, self.shards, self.weight_map, name)
333	        }
334	    }
335	
336	    /// Fused linear qkv: stitch this rank's head-local slice out of each of the
337	    /// three global segments rather than cutting one flat row range.
338	    fn linear_in_proj_qkv(&self, name: &str) -> Result<DeviceMatrix> {
339	        if !self.geometry.is_sharded() {
340	            return self.tensor_2d(name, self.linear_qkv.global, self.hidden);
341	        }
342	        load_tensor_2d_row_stitch(
343	            self.ctx,
344	            self.shards,
345	            self.weight_map,
346	            name,
347	            &self.linear_qkv.segments,
348	            (self.linear_qkv.global, self.hidden),
349	        )
350	    }
351	
352	    /// conv1d channels mirror the fused qkv rows, so they stitch with the same
353	    /// segments scaled into kernel-tap units.
354	    fn linear_conv1d(&self, name: &str) -> Result<DeviceVec> {
355	        if !self.geometry.is_sharded() {
356	            return self.tensor_1d(name);
357	        }
358	        load_tensor_1d_stitch(
359	            self.ctx,
360	            self.shards,
361	            self.weight_map,
362	            name,
363	            &self.linear_conv1d,
364	        )
365	    }
366	
367	    /// Q projection carries a per-head output gate, so its rows shard per head
368	    /// (keeping each head's [q, gate] chunk adjacent), not as one flat range.
369	    fn gated_q_proj(&self, name: &str) -> Result<DeviceMatrix> {
370	        if !self.geometry.is_sharded() {
371	            return self.tensor_2d(name, self.gated_q.global, self.hidden);
372	        }
373	        let (row_offset, rows) = self.gated_q.range;
374	        load_tensor_2d_row_shard(
375	            self.ctx,
376	            self.shards,
377	            self.weight_map,
378	            name,
379	            row_offset,
380	            rows,
381	            (self.gated_q.global, self.hidden),
382	        )
383	    }
384	}
