386	/// Row ranges this rank owns inside the fused global linear-attention qkv
387	/// projection, with the fused global row count the load asserts against. The
388	/// checkpoint stores [all q rows | all k rows | all v rows]; each segment
389	/// contributes its head-local slice so the rank's stitched rows stay
390	/// [q_local | k_local | v_local]. Never reblock across segments — q rows key on
391	/// key heads, v rows on value heads (the gated-q lesson).
392	fn linear_qkv_shard(config: &Config35, geometry: LocalGeometry) -> LinearQkvShard {
393	    let global_q = config.linear_num_key_heads * config.linear_key_head_dim;
394	    let global_k = global_q;
395	    let global_v = config.linear_attn_z_dim();
396	    let (q_rel, q_rows) = geometry.shard_range(global_q);
397	    let (k_rel, k_rows) = geometry.shard_range(global_k);
398	    let (v_rel, v_rows) = geometry.shard_range(global_v);
399	    LinearQkvShard {
400	        segments: [
401	            (q_rel, q_rows),
402	            (global_q + k_rel, k_rows),
403	            (global_q + global_k + v_rel, v_rows),
404	        ],
405	        global: global_q + global_k + global_v,
406	    }
407	}
408	
409	/// The flattened conv1d weight keeps each channel's kernel taps contiguous
410	/// ([channel, 1, kernel_dim]); its channel layout mirrors the fused qkv rows,
411	/// so shard it with the same per-segment ranges scaled by the kernel dim.
412	fn conv1d_shard_segments(qkv: LinearQkvShard, kernel_dim: usize) -> [(usize, usize); 3] {
413	    qkv.segments
414	        .map(|(offset, len)| (offset * kernel_dim, len * kernel_dim))
415	}
416	
417	/// HF/PegaInfer kernels interpret q_proj rows as per-head [q, gate] chunks:
418	/// every head contributes `head_dim` q rows followed by `head_dim` gate rows.
419	/// Keep each local head's q rows adjacent to its gate rows, so the shard is a
420	/// per-head range rather than a flat cut of the fused rows.
421	fn full_attention_gated_q_shard(config: &Config35, geometry: LocalGeometry) -> Shard {
422	    let gated_rows = |heads: usize| heads * config.head_dim * 2;
423	    let local_heads = geometry.local_num_attention_heads();
424	    Shard {
425	        range: (
426	            gated_rows(geometry.rank() * local_heads),
427	            gated_rows(local_heads),
428	        ),
429	        global: gated_rows(config.num_attention_heads),
430	    }
431	}
