583	
584	/// Wrap the matrices one tuning pass samples into cuBLASLt tune candidates.
585	fn sample_mats<'a>(
586	    mats: impl IntoIterator<Item = &'a DeviceMatrix>,
587	) -> Vec<(&'a DeviceMatrix, usize)> {
588	    mats.into_iter().map(|m| (m, 0)).collect()
589	}
