591	fn tune_if_nonempty(
592	    ctx: &DeviceContext,
593	    samples: &[(&DeviceMatrix, usize)],
594	    rows: usize,
595	    n: usize,
596	) -> Result<()> {
597	    if samples.is_empty() {
598	        return Ok(());
599	    }
600	    crate::ops::gemm_lt_tune(ctx, samples, rows, n)
601	}
