89	// SAFETY: A Qwen3.5 model instance is bound to one CUDA device and driven from
90	// one owning scheduler/worker thread at a time. TP constructs one independent
91	// rank-local model per worker; the model is moved between threads only during
92	// startup, never shared for concurrent mutation.
93	unsafe impl Send for Qwen35Model {}
94	unsafe impl Sync for Qwen35Model {}
95	
96	/// Graph slot state + one in-flight prefill transient per decode slot.
97	const STATES_PER_DECODE_SLOT: usize = 2;
98	/// KV-pool floor, also the low-memory fail-fast threshold.
99	const MIN_KV_PAGES: usize = 64;
100	
101	impl Qwen35Model {
102	    /// `max_batch` is the requested concurrent-request cap in `1..=MAX_BATCH`.
103	    pub fn from_safetensors_with_options(
104	        model_path: &str,
105	        enable_cuda_graph: bool,
106	        max_batch: usize,
107	    ) -> Result<Self> {
108	        Self::from_safetensors_with_runtime_and_capacity(
109	            model_path,
110	            ModelRuntimeConfig {
111	                enable_cuda_graph,
112	                ..Default::default()
113	            },
114	            max_batch,
115	        )
116	    }
117	}
118	
119	impl Qwen35Model {
120	    /// `max_batch` is the requested concurrent-request cap in `1..=MAX_BATCH`.
121	    /// It need not be a decode bucket: the physical decode capacity is rounded
122	    /// up to the next `BATCH_BUCKETS` value while the scheduler still admits at
123	    /// most `max_batch` (see #470 and `decode_admission_batch`).
124	    pub(crate) fn from_safetensors(
125	        model_path: &str,
126	        device_ordinal: usize,
127	        max_batch: usize,
128	        prefix_snapshot_bytes: usize,
129	    ) -> Result<Self> {
130	        Self::from_safetensors_with_runtime_and_capacity(
131	            model_path,
132	            ModelRuntimeConfig {
133	                device_ordinal,
134	                prefix_snapshot_bytes,
135	                ..Default::default()
136	            },
137	            max_batch,
138	        )
139	    }
140	
141	    pub(crate) fn from_safetensors_with_runtime_and_capacity(
142	        model_path: &str,
143	        runtime: ModelRuntimeConfig,
144	        max_batch: usize,
145	    ) -> Result<Self> {
146	        anyhow::ensure!(
147	            (1..=super::batch_decode_graph::MAX_BATCH).contains(&max_batch),
148	            "decode batch capacity must be in 1..={}, got {max_batch}",
149	            super::batch_decode_graph::MAX_BATCH,
150	        );
151	        // Requested scheduler admission cap; physical decode capacity is the
152	        // next CUDA-graph bucket >= this (e.g. `--max-batch 5` allocates bucket
153	        // 8 but admits at most 5, see #470). Everything below sizes to the
154	        // physical bucket; only `decode_admission_batch` keeps the request.
155	        let decode_admission_batch = max_batch;
156	        let max_batch = super::batch_decode_graph::bucket_for(max_batch);
157	        info!("Loading Qwen3.5 model from: {}", model_path);
158	        debug!("Initializing GPU device {}", runtime.device_ordinal);
159	        let ctx = DeviceContext::new_with_device(runtime.device_ordinal)?;
160	
161	        let mut config = Config35::from_file(model_path)?;
162	        let tensor_parallel = runtime.tensor_parallel.unwrap_or_default();
163	        let geometry =
164	            LocalGeometry::try_new(&config, tensor_parallel).map_err(anyhow::Error::from)?;
165	        debug!(
166	            "Config: hidden_size={}, num_layers={}, full_attn={}, linear_attn={}, max_position_embeddings={}, tp_rank={}, tp_world_size={}",
167	            config.hidden_size,
168	            config.num_hidden_layers,
169	            config.num_full_attention_layers(),
170	            config.num_hidden_layers - config.num_full_attention_layers(),
171	            config.max_position_embeddings,
172	            geometry.rank(),
173	            geometry.world_size(),
174	        );
175	        let effective_vocab = pegainfer_core::decodable_vocab::decodable_vocab_width(model_path)?;
176	        config
177	            .bound_selection_vocab(effective_vocab)
178	            .map_err(anyhow::Error::from)?;
179	        if config.selection_vocab != effective_vocab {
180	            info!(
181	                "output projection: selection width {} = decodable vocab {} + tile-alignment pad (checkpoint has {})",
182	                config.selection_vocab, effective_vocab, config.vocab_size
183	            );
184	        }
185	
186	        let (shard_paths, weight_map) = load_shard_info_fixed(model_path)?;
187	        debug!("Loading {} safetensor shard(s)", shard_paths.len());
188	        let prefetch = (geometry.world_size() == 1).then(|| WeightPrefetch::spawn(&shard_paths));
189	        let mmaps = mmap_shards(&shard_paths)?;
190	        let shards = deserialize_shards(&mmaps)?;
191	
192	        let t_gpu = Instant::now();
193	        // Weight prefix for Qwen3.5 text model
194	        let wp = "model.language_model";
195	        let src = layers::WeightSource::new(&ctx, &shards, &weight_map, &config, geometry);
196	
197	        debug!("Loading embeddings to GPU");
198	        let embed_tokens = src.tensor_2d(
199	            &format!("{}.embed_tokens.weight", wp),
200	            config.vocab_size,
201	            config.hidden_size,
202	        )?;
203	        debug!(
204	            "embed_tokens: [{}, {}]",
205	            embed_tokens.rows, embed_tokens.cols
206	        );
207	
208	        let lm_head = if config.tie_word_embeddings {
209	            info!("output projection: tied embed_tokens");
210	            None
211	        } else {
212	            let m = src.tensor_2d("lm_head.weight", config.vocab_size, config.hidden_size)?;
213	            info!("output projection: untied lm_head [{}, {}]", m.rows, m.cols);
214	            Some(m)
215	        };
216	
217	        debug!(
218	            "Loading layers to GPU: num_layers={}",
219	            config.num_hidden_layers
220	        );
221	        let mut layers = Vec::with_capacity(config.num_hidden_layers);
222	        for i in 0..config.num_hidden_layers {
223	            let prefix = format!("{}.layers.{}", wp, i);
224	            let layer_type = config.layer_types[i];
225	            layers.push(TransformerBlock35::load(&src, &prefix, layer_type)?);
226	            debug!(
227	                "Loaded layer {}/{}: {:?}",
228	                i + 1,
229	                config.num_hidden_layers,
230	                layer_type
231	            );
232	        }
233	
234	        let norm = src.tensor_1d(&format!("{}.norm.weight", wp))?;
235	
236	        debug!(
237	            "Precomputing partial RoPE cache (rotary_dim={}, max_position_embeddings={})",
238	            config.rotary_dim, config.max_position_embeddings
239	        );
240	        let (cos_cache, sin_cache) = precompute_rope(
241	            &ctx,
242	            &RopeTableSpec {
243	                rotary_dim: config.rotary_dim,
244	                frequency_dim: config.rotary_dim,
245	                max_seq_len: config.max_position_embeddings,
246	                theta: config.rope_theta,
247	            },
248	        )?;
249	
250	        ctx.sync()?;
251	        drop(prefetch);
252	        info!(
253	            "GPU model loaded in {:.0}ms",
254	            t_gpu.elapsed().as_secs_f64() * 1e3
255	        );
256	        if runtime.enable_cuda_graph {
257	            debug!("Decode path CUDA Graph is enabled");
258	        } else {
259	            debug!("Decode path CUDA Graph is disabled");
260	        }
261	        // Paged KV pool for the 8 full-attention layers.
262	        let page_size = 16usize;
263	        let num_full_layers = config.num_full_attention_layers();
264	        let layout = pegainfer_kv_cache::KvLayout::new(
265	            num_full_layers,
266	            geometry.local_num_key_value_heads(),
267	            config.head_dim,
268	            page_size,
269	        );
270	        let decode_kv_layout = DecodeKvLayout::new(
271	            layout.num_layers,
272	            layout.num_kv_heads,
273	            layout.head_dim,
274	            layout.page_size,
275	        )?;
276	        let bytes_per_page = layout.page_stride * std::mem::size_of::<half::bf16>();
277	        let (free_bytes, _total_bytes) = cudarc::driver::result::mem_get_info()
278	            .map_err(|e| anyhow::anyhow!("cuMemGetInfo failed: {e}"))?;
279	        // Reserve space for prefill scratch (GDR chunkwise + per-layer transients)
280	        // before allocating KV pool, so prefill doesn't OOM.
281	        let max_prefill_len = super::prefill::SCRATCH_ESTIMATE_SEQ;
282	        let scratch_reserve = super::prefill_buffers::GdrChunkwiseScratch35::estimate_bytes(
283	            &config,
284	            geometry,
285	            max_prefill_len,
286	        );
287	        let recurrent_reserve = STATES_PER_DECODE_SLOT
288	            * max_batch
289	            * super::recurrent_state::bytes_per_request(&config, geometry);
290	        let prefix_snapshot_bytes = runtime.prefix_snapshot_bytes;
291	        let snapshot_bytes_per_slot = super::recurrent_state::bytes_per_request(&config, geometry);
292	        let snapshot_slots = prefix_snapshot_bytes / snapshot_bytes_per_slot;
293	        anyhow::ensure!(
294	            prefix_snapshot_bytes == 0 || snapshot_slots > 0,
295	            "Qwen3.5 prefix-cache budget is {} MiB, but one recurrent/conv snapshot requires {:.3} MiB",
296	            prefix_snapshot_bytes / (1024 * 1024),
297	            snapshot_bytes_per_slot as f64 / 1024.0 / 1024.0,
298	        );
299	        let snapshot_reserve = snapshot_slots * snapshot_bytes_per_slot;
300	        let min_kv_bytes = MIN_KV_PAGES * bytes_per_page;
301	        anyhow::ensure!(
302	            free_bytes >= scratch_reserve + recurrent_reserve + snapshot_reserve + min_kv_bytes,
303	            "insufficient device memory for Qwen3.5: {} MB free, but prefill scratch needs {} MB, \
304	             recurrent state needs {} MB ({STATES_PER_DECODE_SLOT} x {max_batch} decode slots), \
305	             prefix snapshots need {} MB ({} slots), and the minimal KV pool needs {} MB; \
306	             lower the decode batch capacity (--max-batch) or the prefix-cache budget \
307	             or use a smaller model",
308	            free_bytes / (1024 * 1024),
309	            scratch_reserve / (1024 * 1024),
310	            recurrent_reserve / (1024 * 1024),
311	            snapshot_reserve / (1024 * 1024),
312	            snapshot_slots,
313	            min_kv_bytes / (1024 * 1024),
314	        );
315	        let available = free_bytes - scratch_reserve - recurrent_reserve - snapshot_reserve;
316	        let kv_budget = (available as f64 * 0.85) as usize;
317	        let num_pages = (kv_budget / bytes_per_page).max(MIN_KV_PAGES);
318	        let kv_mb = num_pages * bytes_per_page / (1024 * 1024);
319	        let scratch_mb = scratch_reserve / (1024 * 1024);
320	        let recurrent_mb = recurrent_reserve / (1024 * 1024);
321	        let snapshot_mb = snapshot_reserve / (1024 * 1024);
322	        info!(
323	            "Qwen3.5 KV cache: {num_pages} pages ({kv_mb} MB), prefill scratch reserve: {scratch_mb} MB, recurrent-state reserve: {recurrent_mb} MB ({STATES_PER_DECODE_SLOT} x {max_batch} slots), prefix snapshots: {snapshot_slots} slots ({snapshot_mb} MB), {:.0}% of {:.0} MB free",
324	            kv_budget as f64 / free_bytes as f64 * 100.0,
325	            free_bytes as f64 / 1024.0 / 1024.0
326	        );
327	        let kv_buffer = KvBuffer::new(
328	            &ctx.stream,
329	            num_full_layers,
330	            geometry.local_num_key_value_heads(),
331	            config.head_dim,
332	            page_size,
333	            num_pages,
334	        )?;
335	        // The alignment pad rows are real checkpoint embeddings but not
336	        // decodable tokens, so they must never win selection.
337	        let pad_logit_suppress = if config.selection_vocab > config.decodable_vocab {
338	            let ids: Vec<u32> = (config.decodable_vocab..config.selection_vocab)
339	                .map(|id| id as u32)
340	                .collect();
341	            Some(crate::ops::SuppressIds::upload(
342	                &ctx,
343	                &ids,
344	                config.selection_vocab,
345	            )?)
346	        } else {
347	            None
348	        };
349	
350	        Ok(Self {
351	            ctx,
352	            config,
353	            geometry,
354	            embed_tokens,
355	            lm_head,
356	            layers,
357	            norm,
358	            cos_cache,
359	            sin_cache,
360	            kv_buffer,
361	            decode_kv_layout,
362	            prefix_snapshot_slots: snapshot_slots,
363	            reserved_decode_slots: max_batch,
364	            decode_admission_batch,
365	            tp_comm: None,
366	            pad_logit_suppress,
367	        })
368	    }
369	
370	    pub(crate) fn config(&self) -> &Config35 {
371	        &self.config
372	    }
373	
374	    /// Only the GEMM tuning helper samples this directly; logits go through
375	    /// [`Qwen35Model::output_logits_into`] so the pad-row mask cannot be skipped.
376	    fn output_projection(&self) -> &DeviceMatrix {
377	        self.lm_head.as_ref().unwrap_or(&self.embed_tokens)
378	    }
379	
380	    /// Write selectable logits for `normed` rows: the output-projection GEMM
381	    /// followed by the tile-alignment pad-row mask.
382	    ///
383	    /// The two belong together — a site that ran the GEMM alone would leave the
384	    /// pad rows selectable, which on the wire is an undecodable id fed back into
385	    /// later decode steps rather than a failure — so this is the only way the
386	    /// model produces logits.
387	    pub(crate) fn output_logits_into(
388	        &self,
389	        normed: &HiddenStates,
390	        logits: &mut HiddenStates,
391	    ) -> Result<()> {
392	        let vocab = self.config.selection_vocab;
393	        gemm_rows_into_checked(
394	            &self.ctx,
395	            self.output_projection(),
396	            0,
397	            vocab,
398	            normed,
399	            logits,
400	        )?;
401	        if let Some(suppress) = &self.pad_logit_suppress {
402	            suppress_logits_bf16_in_place(&self.ctx, logits, suppress)?;
403	        }
404	        Ok(())
405	    }
406	
407	    pub(crate) fn ensure_rope_cache_covers(&self, positions: usize) -> Result<()> {
408	        let cache_positions = self.cos_cache.len / self.config.rotary_dim;
409	        anyhow::ensure!(
410	            positions <= cache_positions,
411	            "Qwen3.5 RoPE cache covers {cache_positions} positions, requested {positions}; max_position_embeddings={}",
412	            self.config.max_position_embeddings
413	        );
414	        Ok(())
415	    }
416	
417	    pub(crate) fn device_ctx(&self) -> &DeviceContext {
418	        &self.ctx
419	    }
420	
421	    pub(crate) fn kv_buffer(&self) -> &KvBuffer {
422	        &self.kv_buffer
423	    }
424	
425	    pub(crate) fn prefix_snapshot_slots(&self) -> usize {
426	        self.prefix_snapshot_slots
427	    }
428	
429	    pub(crate) fn attach_tp_comm(&mut self, comm: Comm) {
430	        self.tp_comm = Some(comm);
431	    }
432	
433	    /// Force NCCL connect before any CUDA Graph capture records a collective
434	    /// (lazy connect inside `cuStreamBeginCapture` wedges the capture). NCCL
435	    /// 2.22+ connects per size-selected algorithm, so warm one all-reduce at
436	    /// every decode bucket's message size. No-op without a TP communicator.
437	    pub(crate) fn warmup_tp_collective(&self) -> Result<()> {
438	        if let Some(comm) = &self.tp_comm {
439	            let buckets = super::batch_decode_graph::BATCH_BUCKETS;
440	            let max_elems = buckets.last().unwrap() * self.config.hidden_size;
441	            let mut scratch = self
442	                .ctx
443	                .stream
444	                .alloc_zeros::<half::bf16>(max_elems)
445	                .map_err(|e| anyhow::anyhow!("alloc NCCL warm-up scratch: {e}"))?;
446	            for &bucket in buckets {
447	                let mut view = scratch.slice_mut(0..bucket * self.config.hidden_size);
448	                comm.all_reduce_in_place(&mut view, &ReduceOp::Sum)
449	                    .map_err(|e| {
450	                        anyhow::anyhow!("Qwen3.5 NCCL warm-up all-reduce failed: {e:?}")
451	                    })?;
452	            }
453	            self.ctx
454	                .stream
455	                .synchronize()
456	                .map_err(|e| anyhow::anyhow!("Qwen3.5 NCCL warm-up sync failed: {e}"))?;
457	        }
458	        Ok(())
459	    }
