473	    /// Tune small-batch decode GEMM algorithms on the thread that will capture
474	    /// or replay the CUDA Graph. cuBLASLt plans are thread-local, so scheduler
475	    /// workers and model-local executors must call this after binding CUDA.
476	    /// Repeated calls on the same thread return from the existing plan cache;
477	    /// calls on different worker threads populate separate thread-local plans.
478	    pub(crate) fn tune_decode_gemm_algos(&self) -> Result<()> {
479	        let ctx = &self.ctx;
480	        let hidden = self.config.hidden_size;
481	        let vocab = self.config.selection_vocab;
482	        let geom = self.geometry;
483	        let full_q = geom.local_full_attn_gated_q_dim();
484	        let full_kv = geom.local_full_attn_kv_dim();
485	        let linear_qkv = geom.local_linear_qkv_dim();
486	        let linear_z = geom.local_linear_z_dim();
487	        let linear_ba = geom.local_linear_num_value_heads();
488	        let intermediate = geom.local_intermediate_size();
489	
490	        let full_attn = || {
491	            self.layers
492	                .iter()
493	                .filter_map(|layer| layer.attn.full_attention())
494	        };
495	        let linear_attn = || {
496	            self.layers
497	                .iter()
498	                .filter_map(|layer| layer.attn.linear_attention())
499	        };
500	        let full_q_samples = sample_mats(full_attn().map(|attn| &attn.q_proj));
501	        let full_kv_samples =
502	            sample_mats(full_attn().flat_map(|attn| [&attn.k_proj, &attn.v_proj]));
503	        let full_o_samples = sample_mats(full_attn().map(|attn| &attn.o_proj));
504	        let linear_qkvz_samples = sample_mats(linear_attn().map(|attn| &attn.in_proj_qkvz));
505	        let linear_ba_samples = sample_mats(linear_attn().map(|attn| &attn.in_proj_ba));
506	        let linear_out_samples = sample_mats(linear_attn().map(|attn| &attn.out_proj));
507	        let gate_up_samples = sample_mats(self.layers.iter().map(|layer| &layer.mlp.gate_up_proj));
508	        let down_samples = sample_mats(self.layers.iter().map(|layer| &layer.mlp.down_proj));
509	        let lm_head_samples = sample_mats([self.output_projection()]);
510	
511	        for &n in super::batch_decode_graph::BATCH_BUCKETS
512	            .iter()
513	            .filter(|&&bucket| {
514	                // Keep in sync with MAX_SHARED_SM_DECODE_BATCH: buckets above
515	                // GEMM_LT_MAX_N do not have an independent tuned decode GEMM
516	                // route today, so Shared-SM overlap rejects them at startup.
517	                bucket <= crate::ops::GEMM_LT_MAX_N && bucket <= self.reserved_decode_slots
518	            })
519	        {
520	            tune_if_nonempty(ctx, &full_q_samples, full_q, n)?;
521	            tune_if_nonempty(ctx, &full_kv_samples, full_kv, n)?;
522	            tune_if_nonempty(ctx, &full_o_samples, hidden, n)?;
523	            tune_if_nonempty(ctx, &linear_qkvz_samples, linear_qkv + linear_z, n)?;
524	            tune_if_nonempty(ctx, &linear_ba_samples, 2 * linear_ba, n)?;
525	            tune_if_nonempty(ctx, &linear_out_samples, hidden, n)?;
526	            crate::ops::gemm_lt_tune(ctx, &gate_up_samples, 2 * intermediate, n)?;
527	            crate::ops::gemm_lt_tune(ctx, &down_samples, hidden, n)?;
528	            crate::ops::gemm_lt_tune(ctx, &lm_head_samples, vocab, n)?;
529	        }
530	        Ok(())
531	    }
